package com.example.quickstart;
import android.app.Activity;import android.os.Bundle;import android.text.InputType;import android.widget.*;
public class ProfileActivity extends Activity {
 @Override protected void onCreate(Bundle b){super.onCreate(b);android.content.SharedPreferences prefs=getSharedPreferences("account",MODE_PRIVATE);LinearLayout root=Ui.page(this,"My profile","Your account information.");TextView avatar=Ui.text(this,"👤",54,true,Ui.PURPLE);avatar.setGravity(android.view.Gravity.CENTER);root.addView(avatar,new LinearLayout.LayoutParams(-1,Ui.dp(this,82)));EditText name=Ui.input(this,"Full name",InputType.TYPE_CLASS_TEXT);name.setText(prefs.getString("name","Demo User"));EditText email=Ui.input(this,"Email address",InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS|InputType.TYPE_CLASS_TEXT);email.setText(prefs.getString("email","demo@quickstart.com"));email.setEnabled(false);root.addView(name);root.addView(email);root.addView(Ui.button(this,"Save profile",()->{String n=Ui.value(name);if(n.isEmpty()){Ui.toast(this,"Name cannot be empty");return;}prefs.edit().putString("name",n).apply();Ui.toast(this,"Profile saved");}));root.addView(Ui.button(this,"Change password",()->{android.content.Intent i=new android.content.Intent(this,ForgotPasswordActivity.class);startActivity(i);}));root.addView(Ui.link(this,"Back to dashboard",()->finish())); }
}
